<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\UserInvitation\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Create\InvitationCreateParams;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Create\InvitationCreateUsecase;

class InvitationCreateController
{
    public function __construct(
        private readonly InvitationCreateUsecase $usecase,
        private readonly Context $context,
    ) {
    }

    public function create(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $body   = (array) ($request->getParsedBody() ?? []);

        $attrs   = $request->getAttributes();
        $inviter = $attrs['auth_user'] ?? null;

        $inviterUid   = is_object($inviter) && method_exists($inviter, 'uid') ? (string) $inviter->uid() : '';
        $inviterEmail = is_object($inviter) && method_exists($inviter, 'getEmail') ? (string) $inviter->getEmail() : '';
        $tenantId     = is_object($inviter) && method_exists($inviter, 'getTenantId') ? (string) $inviter->getTenantId() : ($body['tenant_id'] ?? '');

        $params = new InvitationCreateParams(
            tenantName: $tenant,
            tenantId: $tenantId,
            email: (string) ($body['email'] ?? ''),
            invitedByUserUid: $inviterUid,
            invitedByEmail: $inviterEmail,
            baseUrl: $this->context->getBaseUrl(),
            roles: ($body['roles'] ?? null) !== null ? (string) $body['roles'] : null,
            metadataJson: ($body['metadata'] ?? null) !== null ? (string) json_encode($body['metadata']) : null,
            clientId: (string) ($body['client_id'] ?? ''),
            redirectUri: (string) ($body['redirect_uri'] ?? ''),
        );

        $result  = $this->usecase->create($params);
        $payload = json_encode([
            'uid'        => $result->uid,
            'expires_at' => $result->expiresAt->format(\DateTimeInterface::ATOM),
        ]);

        $response->getBody()->write($payload !== false ? $payload : '{}');

        return $response->withStatus(201)->withHeader('Content-Type', 'application/json');
    }
}
